def audit_line(words, banned):
    flagged = 0
    kept = ""
    for i in range(len(words)):
        w = words[i]
        hit = False
        for j in range(len(banned)):
            if banned[j] == w:
                hit = True
        if hit:
            flagged = flagged + 1
        else:
            if kept == "":
                kept = w
            else:
                kept = kept + "," + w
    return kept + "|" + str(flagged)

if __name__ == "__main__":
    assert audit_line(["alpha", "beta", "gamma"], ["beta"]) == "alpha,gamma|1"
    assert audit_line(["x", "y"], []) == "x,y|0"
    print("behavior preserved")
